import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * Keeps the sent messages in memory for the lifetime of the application, so
 * they survive navigating away from the contact view.
 */
@Service
public class ContactMessageRepository {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void save(ContactMessage message) {
        messages.add(0, message);
    }

    /**
     * @return a snapshot of all sent messages, newest first
     */
    public List<ContactMessage> findAllNewestFirst() {
        return List.copyOf(messages);
    }
}
