+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
+
+    private final ContactMessageRepository repository;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+
+    private final Grid<ContactMessage> messages = new Grid<>();
+    private final Dialog unsavedDialog = createUnsavedDialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageRepository repository) {
+        this.repository = repository;
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        // Any edit re-enables Send after a successful send.
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(e -> submit());
+        Shortcuts.addShortcutListener(this, this::submitFromKeyboard, Key.ENTER);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        messages.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        messages.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        messages.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        messages.addColumn(m -> SENT_FORMAT.format(m.sentAt())).setHeader("Sent").setAutoWidth(true);
+        messages.setItems(repository.findAllNewestFirst());
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, messages, unsavedDialog);
+    }
+
+    private void submitFromKeyboard() {
+        if (send.isEnabled()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        resetValidation();
+        if (!validate()) {
+            return;
+        }
+
+        repository.save(new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue(), LocalDateTime.now()));
+
+        // Clearing fires the value change listeners, which enable Send, so disable it afterwards.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+
+        messages.setItems(repository.findAllNewestFirst());
+        Notification.show("Message sent");
+    }
+
+    private void resetValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue();
+
+        if (nameValue.isEmpty()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void invalidate(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            pendingNavigation = event.postpone();
+            unsavedDialog.open();
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    private Dialog createUnsavedDialog() {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsent message");
+        dialog.add(new Paragraph("You have typed a message that has not been sent. Leaving now will discard it."));
+
+        Button keepEditing = new Button("Keep editing", e -> keepEditing());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            if (pendingNavigation != null) {
+                pendingNavigation.proceed();
+                pendingNavigation = null;
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        dialog.getFooter().add(keepEditing, discard);
+        // Escape or a click outside the dialog also means "keep editing".
+        dialog.addDialogCloseActionListener(e -> keepEditing());
+        return dialog;
+    }
+
+    private void keepEditing() {
+        unsavedDialog.close();
+        pendingNavigation = null;
+        // Flow keeps the postponed navigation alive until it is proceeded, and the browser keeps
+        // waiting on it. Drop it and cancel it on the client, or later link clicks are ignored.
+        getUI().ifPresent(ui -> {
+            ui.getInternals().setContinueNavigationAction(null);
+            ui.getInternals().getWrapperElement().executeJs("this.serverConnected($0)", true);
+        });
+    }
+}
