@@ -0,0 +1,117 @@
+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    private Locator button(String text) {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(text).setExact(true));
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private Locator heading(String text) {
+        return page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName(text));
+    }
+
+    private Locator dialog() {
+        return page.locator("vaadin-dialog-overlay");
+    }
+
+    private void open() {
+        page.navigate(getUrl());
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+        assertThat(heading("Contact")).isVisible();
+    }
+
+    @Test
+    void validationSendEnterAndDisabledState() {
+        open();
+        button("Send").click();
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+
+        field("Name").fill("Ann");
+        field("Email").fill("ann@example.com");
+        field("Message").fill("Hello from the browser");
+        assertThat(button("Send")).isEnabled();
+        button("Send").click();
+
+        assertThat(page.locator("vaadin-notification-card").getByText("Message sent")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertThat(field("Message")).hasValue("");
+        assertThat(button("Send")).isDisabled();
+        assertThat(page.getByText("Hello from the browser").first()).isVisible();
+
+        field("Name").fill("Bob");
+        assertThat(button("Send")).isEnabled();
+        field("Phone").fill("123");
+        field("Message").fill("Enter sends");
+        field("Message").press("Enter");
+        assertThat(page.getByText("Enter sends").first()).isVisible();
+        assertThat(field("Name")).hasValue("");
+    }
+
+    @Test
+    void leavingWithInputAsksFirst() {
+        open();
+        field("Name").fill("Carol");
+        aboutLink().click();
+        assertThat(dialog()).isVisible();
+        button("Keep editing").click();
+        assertThat(dialog()).not().isVisible();
+        assertThat(field("Name")).hasValue("Carol");
+
+        // Keeping the edits must not block the next attempt to leave.
+        aboutLink().click();
+        assertThat(dialog()).isVisible();
+        button("Discard").click();
+        assertThat(heading("About")).isVisible();
+    }
+
+    @Test
+    void dismissingDialogWithEscapeAlsoKeepsEditing() {
+        open();
+        field("Name").fill("Dan");
+        aboutLink().click();
+        assertThat(dialog()).isVisible();
+        page.keyboard().press("Escape");
+        assertThat(dialog()).not().isVisible();
+        assertThat(field("Name")).hasValue("Dan");
+
+        aboutLink().click();
+        assertThat(dialog()).isVisible();
+    }
+
+    @Test
+    void emptyFormLeavesWithoutDialog() {
+        open();
+        aboutLink().click();
+        assertThat(heading("About")).isVisible();
+        assertThat(dialog()).hasCount(0);
+    }
+}
diff --git a/src/test/java/com/example/contact/ContactViewTest.java b/src/test/java/com/example/contact/ContactViewTest.java
new file mode 100644
index 0000000..460f3d9
--- /dev/null
+++ b/src/test/java/com/example/contact/ContactViewTest.java
@@ -0,0 +1,237 @@
+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.about.AboutView;
+import java.util.List;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private ContactView open() {
+        return navigate(ContactView.class);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withCaption("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withCaption("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withCaption("Email").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withCaption("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) $(Grid.class).single();
+    }
+
+    private List<ContactMessage> rows() {
+        return grid().getListDataView().getItems().toList();
+    }
+
+    private void fillValid() {
+        name().setValue("Ann");
+        email().setValue("ann@example.com");
+        message().setValue("Hello there");
+    }
+
+    @Test
+    void showsHeadingAndEmptyFormWithEnabledSend() {
+        open();
+        assertEquals("Contact", $(com.vaadin.flow.component.html.H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormShowsAllRequiredErrors() {
+        open();
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        open();
+        name().setValue("Ann");
+        email().setValue("not-an-address");
+        message().setValue("Hi");
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        open();
+        int before = rows().size();
+        name().setValue("Ann");
+        phone().setValue("+358 40 123");
+        message().setValue("Call me");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(before + 1, rows().size());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        open();
+        fillValid();
+        message().setValue("x".repeat(501));
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("x".repeat(501), message().getValue());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        open();
+        fillValid();
+        message().setValue("x".repeat(500));
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void successfulSendNotifiesClearsFormAndDisablesSend() {
+        open();
+        fillValid();
+        test(send()).click();
+
+        assertTrue(find(Notification.class).all().stream()
+                .anyMatch(n -> n.getElement().getProperty("text", "").contains("Message sent")));
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+        assertEquals("Ann", rows().get(0).name());
+    }
+
+    @Test
+    void editingAfterSendReEnablesSend() {
+        open();
+        fillValid();
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        name().setValue("B");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        open();
+        int before = rows().size();
+        fillValid();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, rows().size());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void newestMessageIsFirstAndSurvivesRevisiting() {
+        open();
+        int before = rows().size();
+        fillValid();
+        test(send()).click();
+        name().setValue("Bob");
+        phone().setValue("123");
+        message().setValue("Second");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        open();
+        List<ContactMessage> rows = rows();
+        assertEquals(before + 2, rows.size());
+        assertEquals("Bob", rows.get(0).name());
+        assertEquals("Ann", rows.get(1).name());
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutDialogWhenFormIsEmpty() {
+        open();
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void aboutLinkAsksBeforeLeavingWhenFormHasInput() {
+        open();
+        name().setValue("Ann");
+        test($(RouterLink.class).single()).click();
+
+        assertFalse(getCurrentView() instanceof AboutView);
+        assertTrue($(Dialog.class).single().isOpened());
+    }
+
+    @Test
+    void keepEditingStaysOnView() {
+        open();
+        name().setValue("Ann");
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ann", name().getValue());
+    }
+
+    @Test
+    void discardNavigatesToAbout() {
+        open();
+        name().setValue("Ann");
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
